mapper.update:
UPDATE hospital_doctor
username = #{username}, name = #{name}, avatar = #{avatar}, title = #{title}, title_level = #{titleLevel}, department_id = #{departmentId}, dept_ids = #{deptIds}, introduction = #{introduction}, expertise = #{expertise}, qualifications = #{qualifications}, specialties = #{specialties}, reg_no = #{regNo}, gender = #{gender}, email = #{email}, phone = #{phone}, is_online = #{isOnline}, visit_count = #{visitCount}, rating = #{rating}, sort_order = #{sortOrder}, status = #{status}, update_time = NOW(),
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM hospital_doctor
WHERE username = #{username}
AND id != #{excludeId}

SELECT , dep.name AS department_name FROM hospital_doctor d LEFT JOIN department dep ON dep.id = d.department_id WHERE d.status = 1
AND (d.name LIKE CONCAT('%', #{keyword}, '%') OR d.username LIKE CONCAT('%', #{keyword}, '%') OR d.title LIKE CONCAT('%', #{keyword}, '%'))
AND d.department_id = #{deptId} ORDER BY CASE WHEN d.name LIKE CONCAT(#{keyword}, '%') THEN 0 WHEN d.name LIKE CONCAT('%', #{keyword}, '%') THEN 1 ELSE 2 END, d.sort_order ASC, d.id ASC LIMIT #{limit}
